draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Draw oat grain
  ctx.fillStyle = '#ffd700';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2*Math.PI);
  ctx.fill();

  // Draw heart
  ctx.fillStyle = '#ff0000';
  ctx.beginPath();
  ctx.moveTo(W/2 + 70 + 20*Math.sin(t), H/2 - 20*Math.cos(t));
  ctx.bezierCurveTo(W/2 + 90 + 20*Math.sin(t), H/2 - 50 + 20*Math.cos(t), W/2 + 70 + 20*Math.sin(t), H/2 - 30 + 20*Math.cos(t), W/2 + 50 + 20*Math.sin(t), H/2);
  ctx.bezierCurveTo(W/2 + 30 + 20*Math.sin(t), H/2 - 30 + 20*Math.cos(t), W/2 + 10 + 20*Math.sin(t), H/2 - 50 + 20*Math.cos(t), W/2 + 10 + 20*Math.sin(t), H/2 - 70 + 20*Math.cos(t));
  ctx.fill();

  // Draw cholesterol (downward arrow)
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(W/2 - 20, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 50);
  ctx.lineTo(W/2, H/2 + 80);
  ctx.stroke();

  // Draw stick figure
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2 - 100, H/2 - 50, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 - 30);
  ctx.lineTo(W/2 - 100, H/2 + 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 - 10);
  ctx.lineTo(W/2 - 80, H/2);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 - 10);
  ctx.lineTo(W/2 - 120, H/2);
  ctx.stroke();

  ctx.restore();
}
